  const previewBounds=previewTables.map(worldBounds),previewLeft=Math.min(...previewBounds.map(b=>b.left)),previewTop=Math.min(...previewBounds.map(b=>b.top)),previewWidth=Math.max(...previewBounds.map(b=>b.right))-previewLeft,previewHeight=Math.max(...previewBounds.map(b=>b.bottom))-previewTop;
  const submit=e=>{e.preventDefault();const object=makeObject(type,0,0,{name,rowCount:rows,seatsPerRow:seats,capacity});Object.assign(object,type==='entrance'?{x:hall.room.w/2,y:hall.room.h-object.h/2}:availableSpot(object));onAdd([object]);};
